text:
#attachmentView {
  display: flex;
  flex-direction: column;
  justify-content: stretch;
  /* Allow the area to shrink. */
  min-inline-size: 0;
  overflow: hidden;
  flex: 0 1 auto;

  &.list-expanded {
    /* By design, attachmentView should not take up more than 1/4 of the message
       pane space. */
    max-block-size: min(var(--preferred-height), 25%);
  }
}
